import logging
from taf.config.scf.scf_operations import SCFOperations


class SCFQuery(object):

    def __init__(self, scf_file_path):
        self._scf_file_path = scf_file_path

        self._scf_operations = SCFOperations()
        self._scf_operations.load_scf(self._scf_file_path)

    def is_param_existed(self, name):
        value = self._scf_operations.get_all_values_from_scf(p_name=name)
        if value:
            return True

        logging.debug("{} not existed in scf".format(name))
        return False

    def get_parameter_value(self, name=None, index=-1, **kwargs):
        values = self._scf_operations.get_all_values_from_scf(p_name=name, **kwargs)
        if not values:
            logging.debug('get "{}"={} from scf with kwargs={} failed'.format(name, values, kwargs))
            return None

        value = values[index]
        if value and value.lower() in ["true", "false"]:
            value = value.lower()
        return value

    def get_all_parameter_values(self, name=None, **kwargs):
        return self._scf_operations.get_all_values_from_scf(p_name=name, **kwargs)
